import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { CheckCircle2, Laptop, Loader2, LockKeyhole, ShieldCheck, Smartphone, XCircle } from 'lucide-react';
import { motion } from 'motion/react';
import { useAuth } from '../context/AuthContext';
import { invokePosPayments } from '../lib/posPayments';

export const PosAuth = () => {
  const { systemname, token } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [status, setStatus] = useState<'loading' | 'success' | 'error'>('loading');
  const [message, setMessage] = useState('Checking this one-time pairing code…');
  const [expiresAt, setExpiresAt] = useState<string | null>(null);

  useEffect(() => {
    if (!token || !systemname) {
      setStatus('error');
      setMessage('This terminal link is incomplete. Scan a fresh code from the register.');
      return;
    }
    if (!user) {
      const returnPath = `${location.pathname}${location.search}`;
      navigate(`/auth?redirect=${encodeURIComponent(returnPath)}`, { replace: true });
      return;
    }

    let active = true;
    void invokePosPayments<{ success: true; expiresAt: string; systemName: string }>('pair-confirm', { token })
      .then((result) => {
        if (!active) return;
        setExpiresAt(result.expiresAt);
        setStatus('success');
        setMessage(`This device is now linked to ${result.systemName.replaceAll('-', ' ')}.`);
      })
      .catch((error) => {
        if (!active) return;
        setStatus('error');
        setMessage(error instanceof Error ? error.message : 'This terminal could not be linked.');
      });
    return () => { active = false; };
  }, [location.pathname, location.search, navigate, systemname, token, user]);

  return (
    <div className="flex min-h-screen items-center justify-center bg-[#f4f5f7] p-5 text-slate-950">
      <motion.main initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md rounded-[36px] border border-slate-200 bg-white p-7 text-center shadow-2xl shadow-slate-950/10 sm:p-9">
        <div className={`mx-auto flex h-20 w-20 items-center justify-center rounded-[28px] ${status === 'success' ? 'bg-emerald-500 text-white' : status === 'error' ? 'bg-red-50 text-red-600' : 'bg-slate-950 text-white'}`}>
          {status === 'loading' && <Loader2 className="h-9 w-9 animate-spin" />}
          {status === 'success' && <CheckCircle2 className="h-10 w-10" />}
          {status === 'error' && <XCircle className="h-10 w-10" />}
        </div>
        <span className="mt-6 inline-flex items-center gap-2 rounded-full bg-slate-100 px-4 py-2 text-xs font-bold uppercase tracking-[0.14em] text-slate-600"><LockKeyhole className="h-4 w-4" /> Owner approval</span>
        <h1 className="mt-4 text-3xl font-black tracking-tight">{status === 'loading' ? 'Linking terminal' : status === 'success' ? 'Terminal linked' : 'Link failed'}</h1>
        <p className="mt-3 text-sm leading-6 text-slate-500">{message}</p>

        {status === 'success' && (
          <div className="mt-7 rounded-[26px] border border-emerald-100 bg-emerald-50 p-5 text-left">
            <div className="flex items-center gap-3"><Smartphone className="h-5 w-5 text-emerald-700" /><p className="font-bold text-emerald-950">Secure device session active</p></div>
            <div className="mt-4 flex items-center justify-between rounded-full bg-white px-4 py-3 text-xs font-semibold text-slate-600"><span>Expires</span><span>{expiresAt ? new Date(expiresAt).toLocaleString() : 'Automatically'}</span></div>
          </div>
        )}

        <div className="mt-7 flex items-start gap-3 rounded-[22px] bg-slate-50 p-4 text-left text-xs leading-5 text-slate-500"><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-slate-700" /><span>The register receives a scoped POS session, never your account password or reusable login token.</span></div>

        {status === 'success' ? (
          <button onClick={() => window.close()} className="mt-6 flex min-h-12 w-full items-center justify-center gap-2 rounded-full bg-slate-950 px-5 py-3 text-sm font-bold text-white"><Laptop className="h-4 w-4" /> Return to the register</button>
        ) : status === 'error' ? (
          <button onClick={() => navigate('/workspace')} className="mt-6 min-h-12 w-full rounded-full bg-slate-950 px-5 py-3 text-sm font-bold text-white">Open Wersee Workspace</button>
        ) : null}
      </motion.main>
    </div>
  );
};
